export function getAuthTokenAccessorsIndexQueryKey(
  args: InferRequestType<typeof client.auth.token.accessors.index.$get>,
) {
  return ['auth', '/auth/token/accessors/', args] as const
}

export function getAuthTokenAccessorsIndexQueryOptions<
  TData = Awaited<
    ReturnType<
      typeof parseResponse<Awaited<ReturnType<typeof client.auth.token.accessors.index.$get>>>
    >
  >,
  TError = DefaultError,
>(
  args: InferRequestType<typeof client.auth.token.accessors.index.$get>,
  options?: ClientRequestOptions,
) {
  return queryOptions<
    Awaited<
      ReturnType<
        typeof parseResponse<Awaited<ReturnType<typeof client.auth.token.accessors.index.$get>>>
      >
    >,
    TError,
    TData,
    ReturnType<typeof getAuthTokenAccessorsIndexQueryKey>
  >({
    queryKey: getAuthTokenAccessorsIndexQueryKey(args),
    queryFn({ signal }) {
      return parseResponse(
        client.auth.token.accessors.index.$get(args, {
          ...options,
          init: { ...options?.init, signal },
        }),
      )
    },
  })
}

